[CmdletBinding()]
param([string]$ProjectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path)
$ErrorActionPreference='Stop';$fixture=Join-Path $ProjectRoot 'ES/Automation/WebPageStudio/fixtures/release-receipt.valid.json';$budget=Join-Path $ProjectRoot 'ES/Automation/WebPageStudio/performance-budget.yaml';$o=Get-Content -Raw -Encoding UTF8 $fixture|ConvertFrom-Json;$h=(Get-FileHash -LiteralPath $budget -Algorithm SHA256).Hash.ToLowerInvariant();$o.budgets|Add-Member -NotePropertyName budgetConfigHash -NotePropertyValue $h -Force
$vp=Join-Path $env:TEMP 'es-web-release-budget-valid.json';[IO.File]::WriteAllText($vp,($o|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));$v=(& (Join-Path $PSScriptRoot 'Test-ESWebReleaseAcceptanceReceipt.ps1') -ReceiptPath $vp -BudgetPath $budget 2>$null)-join "`n"|ConvertFrom-Json
$o.budgets.budgetConfigHash=('0'*64);$dp=Join-Path $env:TEMP 'es-web-release-budget-drift.json';[IO.File]::WriteAllText($dp,($o|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));$d=(& (Join-Path $PSScriptRoot 'Test-ESWebReleaseAcceptanceReceipt.ps1') -ReceiptPath $dp -BudgetPath $budget 2>$null)-join "`n"|ConvertFrom-Json
